  public static function find(string $slug): ?array {
    foreach (self::items() as $topic => $items) {
      foreach ($items as $item) {
        if ($item['slug'] === $slug) {
          return $item + ['topic' => $topic];
        }
      }
    }
    return NULL;
  }

  public static function aiItems(): array {
    $approved = [];
    foreach (self::items() as $topic => $items) {
      foreach ($items as $item) {
        $item += ['topic' => $topic];
        if (KnowledgeApproval::isAiApproved($item)) {
          $approved[] = $item;
        }
      }
    }
    return $approved;
  }

