      'houtrot-kozijnen' => [['Zoek eerst de vochtbron', 'Houtrot is een gevolg van langdurige vochtbelasting. Kijk daarom naar schilderwerk, open verbindingen, glasafdichting, detaillering, afwatering en aansluitingen voordat alleen het aangetaste hout wordt hersteld.'], ['Bepaal de werkelijke omvang', 'Zichtbare aantasting kan kleiner zijn dan de schade in het hout. Plaats, diepte en kwaliteit van het omliggende materiaal bepalen of plaatselijk herstel technisch verantwoord is.'], ['Herstel oorzaak én materiaal', 'Alleen rot hout vervangen zonder de vochtbelasting weg te nemen geeft kans op herhaling. De reparatie moet daarom onderdeel zijn van een complete herstelmaatregel.']],
      'tocht-langs-kozijnen' => [['Lokaliseer de luchtlek', 'Tocht kan ontstaan bij draaiende delen, rubbers, glaslatten, aansluitnaden of de overgang tussen kozijn en gevel. Vaststellen waar lucht binnenkomt voorkomt dat op de verkeerde plek wordt afgedicht.'], ['Controleer afstelling en vervorming', 'Een nieuw rubber helpt niet wanneer een raam of deur onvoldoende aandrukt, is vervormd of verkeerd staat afgesteld. Beslag en maatvoering horen daarom bij de controle.'], ['Dicht niet zonder naar ventilatie te kijken', 'Ongecontroleerde kieren beperken is meestal wenselijk, maar aanwezige ventilatievoorzieningen moeten hun functie behouden.']],
      'schilderwerk-kozijnen' => [['Beoordeel meer dan de verflaag', 'Bladdering, scheuren, open verbindingen en verkleuring kunnen wijzen op vocht of onderliggende aantasting. Alleen overschilderen kan het probleem tijdelijk aan het zicht onttrekken.'], ['Kijk naar belasting per gevel', 'Zon, regen, detaillering en ligging verschillen per gevel en onderdeel. Daardoor hoeft niet ieder kozijn op hetzelfde moment dezelfde behandeling nodig te hebben.'], ['Koppel schilderwerk aan technisch herstel', 'Herstel van kit, verbindingen, houtschade en beglazingsdetails hoort vóór of tijdens het schilderwerk te worden meegenomen wanneer die onderdelen de bescherming beïnvloeden.']],
      'rubbers-kozijnen-vervangen' => [['Controleer eerst de sluiting', 'Een kier bij een rubber kan komen door veroudering van de dichting, maar ook door verkeerde afstelling, vervorming of onvoldoende aandruk van het draaiende deel.'], ['Beoordeel profiel en aansluiting', 'Vervangende dichtingen moeten passen bij profiel, sponning en benodigde vervorming. Alleen een dikker rubber toepassen is niet automatisch een goede oplossing.'], ['Test na herstel de functie', 'Na vervanging of afstelling moeten bediening, sluitdruk en aansluiting opnieuw worden gecontroleerd.']],
      'hang-en-sluitwerk-kozijnen' => [['Maak onderscheid tussen afstellen en slijtage', 'Klemmen of zwaar sluiten kan door afstelling komen, terwijl speling of beschadigde onderdelen op slijtage kan wijzen. Eerst vaststellen voorkomt onnodige vervanging.'], ['Controleer het complete draaiende deel', 'Scharnieren, sluitpunten, beslag, bevestigingen en vervorming van raam of deur werken samen. Een probleem op één punt kan elders worden veroorzaakt.'], ['Neem veiligheid en gebruik mee', 'Bij intensief gebruik, vluchtfuncties of bereikbare geveldelen kunnen andere eisen relevant zijn dan bij een weinig gebruikt raam.']],
      'aluminium-kozijnen-corrosie' => [['Bepaal welk type aantasting zichtbaar is', 'Oppervlaktevervuiling, beschadiging van de coating en daadwerkelijke corrosie vragen niet dezelfde aanpak. Plaats en patroon geven aanwijzingen over de oorzaak.'], ['Controleer materiaalcontact en vocht', 'Contact met andere materialen, zouten, blijvende vochtbelasting en beschadigde oppervlaktebehandeling kunnen aantasting versnellen.'], ['Herstel pas na oorzaakanalyse', 'Reinigen of lokaal bijwerken heeft weinig waarde wanneer de belastende situatie blijft bestaan.']],
      'levensduur-kozijnen' => [['Gebruik leeftijd niet als vervangingscriterium', 'Twee even oude kozijnen kunnen door materiaal, ligging, detaillering en onderhoud een sterk verschillende conditie hebben.'], ['Beoordeel kritieke onderdelen', 'Dorpels, verbindingen, draaiende delen, afdichtingen, beglazing en gevelaansluitingen geven samen een beter beeld van de resterende bruikbaarheid.'], ['Koppel levensduur aan het onderhoudsscenario', 'De relevante vraag is niet alleen hoe lang het kozijn technisch nog mee kan, maar ook welke onderhoudskosten en toekomstige prestaties daarbij horen.']],
      'condens-tussen-glasbladen' => [['Bepaal eerst waar de condens zit', 'Condens aan de binnenzijde, buitenzijde en tussen de glasbladen heeft niet dezelfde betekenis. Vocht of waas tussen de glasbladen bevindt zich in de afgesloten spouw van het isolatieglas.'], ['Kijk ook naar de beglazing als systeem', 'Bij vervanging is het verstandig ook randafdichting, glasoplegging, sponning en vochtbelasting rondom de ruit te beoordelen.'], ['Controleer voordat u vervangt', 'Leg vast welke ruit is aangedaan en controleer maat, glasopbouw en toestand van het kozijn zodat vervanging niet op aannames wordt besteld.']],
      'hrpp-bestaande-kozijnen' => [['Controleer eerst het bestaande kozijn', 'Sponning, glaslatten, ondersteuning, kierdichting en staat van het kozijn bepalen mede of een andere glasopbouw passend kan worden aangebracht.'], ['Neem ventilatie mee', 'Een betere isolatie en luchtdichtheid veranderen het comfort en de vochtbalans. Gecontroleerde ventilatie blijft daarom onderdeel van de beoordeling.'], ['Controleer maat en gewicht', 'Dikte, gewicht en randvoorwaarden van de nieuwe ruit moeten passen bij kozijn en draaiende delen.']],
      'triple-glas-bestaande-kozijnen' => [['Controleer ruimte en draagvermogen', 'Triple glas is doorgaans dikker en zwaarder dan bestaande isolerende beglazing. Sponning, glaslatten, beslag en ondersteuning moeten daarvoor geschikt zijn.'], ['Vergelijk de meerwaarde met de rest van de gevel', 'Een hoge glasprestatie levert niet automatisch hetzelfde resultaat wanneer kozijn, aansluitingen of andere geveldelen duidelijk minder presteren.'], ['Neem uitvoering mee in de keuze', 'Bereikbaarheid, ruitafmetingen en montagegewicht kunnen bepalen of een theoretisch mogelijke oplossing praktisch verstandig is.']],
      'veiligheidsglas-wanneer' => [['Begin bij positie en gebruik', 'De noodzaak en soort veiligheidsglas hangen samen met waar de ruit zit en hoe mensen ermee in aanraking kunnen komen.'], ['Maak onderscheid tussen risico’s', 'Letselbeperking, doorvalbeveiliging, inbraakvertraging en andere functies vragen niet automatisch dezelfde glasopbouw.'], ['Leg de projectsituatie vast', 'Afmetingen, onderzijde en bovenzijde van het glas, gebruiksfunctie en aangrenzende vloer- of loopzones zijn relevante invoer voor een juiste beoordeling.']],
      'thermische-breuk-glas' => [['Zoek naar temperatuurverschillen', 'Een thermische breuk kan ontstaan wanneer delen van dezelfde ruit sterk verschillend opwarmen. Zon en schaduw, verwarming, folie of objecten dicht achter het glas kunnen bijdragen.'], ['Sluit andere breukoorzaken niet uit', 'Breukbeeld en omstandigheden moeten worden beoordeeld; niet iedere spontane glasbreuk is automatisch thermisch.'], ['Beoordeel de vervangende glaskeuze', 'Als de belasting blijft bestaan, moet bij vervanging worden bekeken of glasopbouw of situatie moet worden aangepast.']],
      'geluidswerend-glas' => [['Bepaal eerst de geluidsbron', 'Verkeer, stemgeluid en andere bronnen hebben verschillende karakteristieken. Het gewenste resultaat moet daarom concreet worden gemaakt.'], ['Zoek de zwakste route', 'Kieren, ventilatieroosters, lichte panelen en gevelaansluitingen kunnen het effect van beter glas beperken.'], ['Beoordeel de complete gevelopbouw', 'Een glaskeuze is pas zinvol wanneer duidelijk is welke prestatie de overige onderdelen kunnen ondersteunen.']],
