      'glasdikte-en-afmetingen' => [['Leg de geometrie correct vast', 'Breedte, hoogte, glasopbouw en positie zijn basisgegevens. Bij afwijkende vormen of grote ruiten zijn ook ondersteuning en randvoorwaarden relevant.'], ['Beoordeel de belasting', 'Wind, eigen gewicht, gebruik en eventuele veiligheidsfunctie beïnvloeden de benodigde opbouw.'], ['Laat twijfel berekenen', 'Wanneer vuistregels of standaardopbouwen onvoldoende zekerheid geven, is projectspecifieke technische controle nodig.']],
      'lekkage-rond-kozijn' => [['Begin buiten én binnen', 'Leg de zichtbare vochtplek binnen vast, maar controleer ook de buitenzijde en bovengelegen aansluitingen. Water kan zich door constructies verplaatsen.'], ['Koppel het probleem aan omstandigheden', 'Windrichting, regenintensiteit en moment van optreden helpen onderscheid maken tussen mogelijke routes.'], ['Test gericht wanneer kijken niet genoeg is', 'Bij een onduidelijke route kan gericht aanvullend onderzoek nodig zijn voordat herstel wordt gekozen.']],
      'kitvoegen-vervangen' => [['Beoordeel hechting en vervorming', 'Scheuren, loslaten, verharding en vervorming zeggen meer dan verkleuring alleen.'], ['Controleer de voeggeometrie', 'Breedte, diepte, rugvulling en aansluiting op de ondergrond beïnvloeden hoe de voeg beweging kan opnemen.'], ['Los de oorzaak van overbelasting op', 'Een nieuwe kitvoeg faalt opnieuw wanneer beweging, vocht of slechte ondergrond niet wordt meegenomen.']],
      'koudebrug-herkennen' => [['Kijk naar patroon en omstandigheden', 'Een plaatselijk koud oppervlak, condens of schimmel kan op een thermisch zwakke plek wijzen, maar gebruik en binnenklimaat beïnvloeden hetzelfde beeld.'], ['Vergelijk binnen- en buitensituatie', 'Constructieopbouw, aansluitdetails, temperatuur en luchtvochtigheid zijn nodig om een vermoeden beter te onderbouwen.'], ['Meet wanneer de oorzaak onzeker blijft', 'Oppervlaktetemperatuur, vocht en eventueel thermografisch onderzoek kunnen helpen, mits de meetomstandigheden geschikt zijn.']],
      'scheuren-gevel' => [['Leg vorm en verloop vast', 'Richting, breedte, lengte en plaats van een scheur geven informatie over mogelijke beweging.'], ['Kijk of de scheur actief is', 'Een oude stabiele scheur vraagt een andere benadering dan scheurvorming die aantoonbaar verder ontwikkelt.'], ['Herstel pas na duiding', 'Dichtsmeren zonder oorzaak te begrijpen kan alleen het symptoom tijdelijk verbergen. Bij twijfel over constructieve betekenis is specialistische beoordeling nodig.']],
      'voegwerk-gevel-herstellen' => [['Bepaal de omvang', 'Plaatselijk uitgesleten voegwerk is iets anders dan brede aantasting over een gevelvlak.'], ['Controleer metselwerk en vochtbelasting', 'Voegen functioneren samen met stenen, detaillering en waterbelasting. Alleen het voegmateriaal beoordelen is te beperkt.'], ['Kies herstel passend bij bestaand werk', 'Materiaal, hardheid, voegprofiel en uitvoeringsmethode moeten aansluiten bij het bestaande metselwerk.']],
      'afspattende-bakstenen' => [['Onderzoek vocht en belasting', 'Afspatting kan meerdere oorzaken hebben. Leg ligging, patroon, vochtbelasting en toestand van omliggende stenen vast.'], ['Bepaal of het lokaal of structureel terugkomt', 'Enkele beschadigde stenen kunnen plaatselijk worden aangepakt; herhaald patroon vraagt om onderzoek naar achterliggende omstandigheden.'], ['Voorkom cosmetisch herstel zonder oorzaak', 'Alleen beschadigde oppervlakken bijwerken helpt niet wanneer vocht- of vorstbelasting blijft bestaan.']],
      'vocht-in-spouwmuur' => [['Zoek de route door de gevel', 'Regenwater kan via verschillende onderdelen in of door de spouw worden geleid. De binnenvlek is daarom geen bewijs van de intredeplaats.'], ['Controleer details en vervuiling', 'Aansluitingen, lateien, spouwankers, isolatie en mogelijke speciebaarden kunnen relevant zijn.'], ['Onderzoek gericht bij verborgen oorzaken', 'Wanneer de spouw niet zichtbaar beoordeeld kan worden, kan plaatselijk nader onderzoek nodig zijn voordat herstel wordt bepaald.']],
      'dilatatievoegen-gevel' => [['Controleer of beweging kan worden opgenomen', 'Een dilatatie moet voldoende ruimte en een passend voegdetail hebben om verwachte beweging te kunnen volgen.'], ['Let op scheuren naast de voeg', 'Scheurvorming nabij een dilatatie kan erop wijzen dat beweging niet op de bedoelde plaats wordt opgenomen.'], ['Beoordeel de volledige voeg', 'Afdichting, ondergrond, continuïteit en aansluitingen aan kozijnen of andere bouwdelen horen bij de controle.']],
      'onderhoud-of-renovatie' => [['Kijk naar herhaling en samenhang', 'Wanneer dezelfde reparaties terugkomen of meerdere bouwdelen elkaar beïnvloeden, wordt alleen incidentgericht herstellen steeds minder logisch.'], ['Vergelijk scenario’s', 'Directe kosten zijn niet het enige criterium. Ook resterende levensduur, gevolgschade, bereikbaarheid, hinder en toekomstige onderhoudsbehoefte horen in de afweging.'], ['Maak de keuze controleerbaar', 'Leg per scenario vast wat wordt hersteld, welke prestatie wordt verwacht en welke risico’s of werkzaamheden blijven staan.']],
      'schilderwerk-plannen' => [['Plan op conditie, niet alleen kalender', 'Vaste cycli zijn een hulpmiddel, maar ligging, materiaal en actuele staat bepalen of onderhoud eerder of later nodig is.'], ['Inspecteer kwetsbare details', 'Onderkanten, verbindingen, glasdetails en horizontale delen kunnen sneller achteruitgaan dan grote zichtvlakken.'], ['Combineer met technisch herstel', 'Schilderwerk is het juiste moment om kleine gebreken te herstellen voordat ze groter worden.']],
      'planmatig-of-correctief' => [['Gebruik correctief onderhoud bewust', 'Een defect herstellen wanneer het optreedt kan passend zijn bij laag risico en beperkte gevolgschade.'], ['Plan waar uitval of schade duur wordt', 'Bij kritieke bouwdelen helpt vooraf plannen om veiligheid, waterdichtheid, bereikbaarheid en budget beter te beheersen.'], ['Combineer beide strategieën', 'Niet ieder onderdeel hoeft dezelfde onderhoudsstrategie te krijgen. Risico en functie bepalen wat logisch is.']],
      'onderhoud-bundelen' => [['Zoek gedeelde kosten en hinder', 'Steiger, hoogwerker, afzetting, bewonerscommunicatie en bereikbaarheid kunnen meerdere werkzaamheden bedienen.'], ['Controleer technische volgorde', 'Bundelen is alleen voordelig wanneer werkzaamheden elkaar niet hinderen en details in de juiste volgorde worden uitgevoerd.'], ['Vergelijk totaal in plaats van losse posten', 'Neem ook toekomstige bereikbaarheid, resterende levensduur en herhaling van hinder mee in de afweging.']],
      'bouwbegeleiding-wanneer' => [['Zorg voor regie vóórdat de uitvoering begint', 'Onafhankelijke bouwbegeleiding is vooral waardevol wanneer u als opdrachtgever grip wilt houden op kwaliteit, planning, kosten en technische keuzes zonder zelf dagelijks op het werk aanwezig te zijn.'], ['Controleer tijdens het werk, niet alleen achteraf', 'Door afspraken, details, afwijkingen en voortgang tijdens de uitvoering vast te leggen, kunnen problemen worden bijgestuurd voordat ze bij oplevering tot discussie, herstelwerk of extra kosten leiden.'], ['Spreek bevoegdheden vooraf af', 'Leg vast wie mag besluiten, welke afwijkingen eerst akkoord nodig hebben en hoe bevindingen worden teruggekoppeld.']],
      'bouwbegeleiding-controlepunten' => [['Maak vooraf duidelijk wat gecontroleerd wordt', 'De controlepunten volgen uit contractstukken, tekeningen, technische eisen, planning en kritieke uitvoeringsmomenten. Zo is vooraf duidelijk waarop de uitvoering wordt beoordeeld.'], ['Leg afwijkingen en besluiten aantoonbaar vast', 'Foto’s, bevindingen, afspraken, meer- en minderwerk en openstaande acties horen in één dossier.'], ['Controleer op het juiste moment', 'Sommige details zijn na dichtzetten niet meer zichtbaar. De planning van controles moet daarom aansluiten op kritieke uitvoeringsmomenten.']],
      'oplevering-restpunten' => [['Begin de oplevering al tijdens de uitvoering', 'Tussentijdse controles maken gebreken en onafgemaakte onderdelen eerder zichtbaar, zodat herstel kan worden ingepland voordat het werk als gereed wordt beschouwd.'], ['Maak ieder restpunt controleerbaar', 'Leg per punt vast wat niet voldoet, waar het zich bevindt, wie actie neemt en wanneer nacontrole plaatsvindt.'], ['Sluit pas na verificatie', 'Een melding dat iets is hersteld is niet hetzelfde als een gecontroleerde afhandeling.']],
      'renovatie-bewoners-hinder' => [['Plan vanuit het gebruik van het gebouw', 'Bereikbaarheid, geluid, stof, tijdelijke afsluitingen en voorzieningen bepalen hoe bewoners en gebruikers de uitvoering ervaren.'], ['Communiceer vóórdat hinder ontstaat', 'Planning, toegang, veiligheidsmaatregelen, contactpersonen en wijzigingen moeten tijdig en begrijpelijk worden gedeeld.'], ['Maak uitzonderingen onderdeel van de voorbereiding', 'Bij kwetsbare bewoners, afwijkende toegang of bijzondere gebruikssituaties is vooraf een passende werkwijze nodig.']],
      'glas-vervangen-verduurzamen' => [['Beoordeel eerst wat behouden blijft', 'Nieuw glas moet technisch passen bij kozijn, sponning, beslag en resterende levensduur.'], ['Kijk naar de hele gebouwschil', 'Het comfort- en energie-effect hangt ook af van kierdichting, gevel, ventilatie en andere zwakke delen.'], ['Vergelijk met het natuurlijke onderhoudsmoment', 'Als kozijnen of gevel binnenkort toch ingrijpend onderhoud vragen, kan combineren logischer zijn dan glas als losse maatregel.']],
      'isoleren-en-ventileren' => [['Minder lekverlies verandert de luchtverversing', 'Na isoleren en kierdichten kan ongecontroleerde luchttoevoer afnemen. De benodigde ventilatie moet daarom bewust worden georganiseerd.'], ['Kijk naar vochtproductie en gebruik', 'Bewoning, douchen, koken en bezetting beïnvloeden hoeveel vocht en verontreiniging moet worden afgevoerd.'], ['Beoordeel maatregelen als één systeem', 'Isolatie, luchtdichtheid en ventilatie moeten samen een gezond en comfortabel binnenklimaat ondersteunen.']],
      'gevelisolatie-aandachtspunten' => [['Begin bij de bestaande gevel', 'Materiaal, vochtbelasting, scheuren, aansluitingen en bestaande isolatie bepalen welke oplossingen technisch passend kunnen zijn.'], ['Werk details vooraf uit', 'Ramen, deuren, dakranden, plinten en doorvoeren zijn bepalend voor continuïteit van isolatie en waterdichting.'], ['Beoordeel vocht en uiterlijk', 'Een isolatiemaatregel verandert temperatuur- en vochtgedrag en kan ook vergunning- of esthetische gevolgen hebben.']],
      'verduurzamen-in-volgorde' => [['Start met toestand en doel', 'Bepaal eerst welke bouwdelen technisch aandacht vragen en welk resultaat u wilt bereiken.'], ['Respecteer technische afhankelijkheden', 'Een maatregel kan latere werkzaamheden moeilijker of duurder maken. Volgorde moet daarom rekening houden met gevel, glas, ventilatie en installaties.'], ['Koppel aan investeringsmomenten', 'Door maatregelen te combineren met gepland onderhoud kan dubbel werk worden voorkomen.']],
      'kierdichting-verduurzamen' => [['Vind eerst de ongecontroleerde lekken', 'Niet iedere opening is ongewenst: ventilatievoorzieningen hebben een functie. Maak daarom onderscheid tussen bedoelde toevoer en ongecontroleerde kieren.'], ['Controleer aansluitingen en draaiende delen', 'Kierdichting kan zitten in rubbers, beslag, aansluitnaden en bouwkundige details.'], ['Borg ventilatie na verbetering', 'Een luchtdichter gebouw vraagt om voldoende beheerste luchtverversing.']],
      'spouwmuur-naisoleren' => [['Onderzoek de spouw vóór uitvoering', 'Breedte, bestaande isolatie, vervuiling en onderbrekingen bepalen of de spouw geschikt is voor de beoogde maatregel.'], ['Controleer de buitengevel', 'Sterke vochtbelasting, beschadigd voegwerk of andere gebreken kunnen eerst aandacht vragen.'], ['Leg onzekerheden vast', 'Als delen van de spouw niet controleerbaar zijn, moet duidelijk zijn welke aannames worden gedaan en welk risico daarbij blijft bestaan.']],
      'zonwering-oververhitting' => [['Bepaal waar de warmtelast ontstaat', 'Oriëntatie, glasoppervlak, zoninstraling, interne warmte en gebruik bepalen samen het risico op hoge binnentemperaturen.'], ['Voorkom alleen symptoombestrijding', 'Koeling kan warmte afvoeren, terwijl buitenzonwering of andere bouwkundige maatregelen de instraling kunnen beperken. Welke aanpak past, is projectspecifiek.'], ['Neem bediening en gebruik mee', 'Een maatregel werkt alleen goed wanneer deze op het juiste moment wordt gebruikt of automatisch wordt geregeld.']],
      'verduurzaming-combineren-onderhoud' => [['Gebruik het moment dat een bouwdeel toch wordt aangepakt', 'Bereikbaarheid, demontage en afwerking hoeven dan niet volledig voor een tweede project te worden herhaald.'], ['Controleer de technische samenhang', 'Een energetische verbetering moet passen bij resterende bouwdelen, ventilatie en aansluitdetails.'], ['Maak scenario’s over meerdere jaren', 'Niet alles hoeft tegelijk. Een gefaseerd plan kan investeringen koppelen aan logische vervangings- en onderhoudsmomenten.']],
      'mjop-wat-is-het' => [['Een MJOP moet meer zijn dan een kalender', 'Een bruikbaar plan koppelt bouwdelen en maatregelen aan conditie, timing, hoeveelheden en verwachte kosten.'], ['Onderbouw waarom iets wanneer gebeurt', 'Prioriteit volgt uit risico, ontwikkeling en technische samenhang; niet alleen uit een theoretische levensduur.'], ['Actualiseer na inspectie en uitvoering', 'Nieuwe bevindingen, uitgevoerde werkzaamheden en prijsontwikkeling horen terug te komen in de planning.']],
      'gebrek-urgent' => [['Beoordeel het gevolg van niets doen', 'Veiligheid, waterindringing, gevolgschade, functieverlies en snelheid van verslechtering bepalen mede de urgentie.'], ['Maak verschil tussen urgent en belangrijk', 'Een kostbare toekomstige maatregel kan belangrijk zijn zonder vandaag acuut te zijn. Dat onderscheid helpt bij prioriteren.'], ['Leg tijdelijke maatregelen vast', 'Als definitief herstel niet direct kan, moet duidelijk zijn welke tijdelijke beheersmaatregel geldt en wanneer opnieuw wordt beoordeeld.']],
      'inspectie-frequentie' => [['Stem frequentie af op risico', 'Een kwetsbaar of kritisch bouwdeel vraagt mogelijk vaker aandacht dan een stabiel onderdeel met lage gevolgen bij uitval.'], ['Gebruik eerdere bevindingen', 'Verslechtering, reparaties en terugkerende klachten geven aanleiding om inspectie-interval aan te passen.'], ['Combineer inspecties waar logisch', 'Bereikbaarheid en samenhang kunnen het efficiënt maken meerdere bouwdelen in één opname te beoordelen.']],
      'onderhoud-prioriteren' => [['Begin met veiligheid en gevolgschade', 'Werkzaamheden met grote risico’s bij uitstel horen anders te worden gewogen dan voornamelijk esthetische gebreken.'], ['Vergelijk ontwikkeling en kosten', 'Een gebrek dat snel verslechtert kan eerder aandacht verdienen omdat later herstel omvangrijker wordt.'], ['Maak keuzes expliciet', 'Leg vast waarom iets nu, later of niet wordt uitgevoerd. Zo blijft de planning controleerbaar.']],
      'conditiemeting-gebouw' => [['Gebruik de score als gestructureerde waarneming', 'Een conditiescore helpt gebreken en toestand vergelijkbaar vast te leggen.'], ['Voeg oorzaak en risico toe', 'Dezelfde score kan bij verschillende bouwdelen een andere betekenis hebben voor veiligheid, gevolgschade of gebruik.'], ['Vertaal conditie niet automatisch naar vervanging', 'De maatregel volgt uit conditie, oorzaak, functie, risico en gewenste resterende levensduur samen.']],
      'onderhoudsbudget-reserveren' => [['Bouw het budget op uit verwachte maatregelen', 'Hoeveelheden, prijsniveau en geplande uitvoering geven een betere basis dan alleen historische uitgaven.'], ['Maak onzekerheid zichtbaar', 'Vroege ramingen bevatten onzekerheden in scope, prijzen en verborgen gebreken. Die horen expliciet in de reservering of bandbreedte.'], ['Actualiseer periodiek', 'Prijsontwikkeling, inspectieresultaten en gewijzigde prioriteiten veranderen de toekomstige kasbehoefte.']],
      'onderhoud-uitstellen-risico' => [['Bepaal wat er tijdens uitstel kan veranderen', 'Kijk naar snelheid van verslechtering, veiligheid, waterdichtheid, gevolgschade en beschikbaarheid van tijdelijke maatregelen.'], ['Vergelijk besparing met toekomstig risico', 'Een jaar later uitvoeren kan financieel logisch zijn, maar niet wanneer daardoor een veel grotere herstelomvang ontstaat.'], ['Leg de uitstelbeslissing vast', 'Noteer uitgangspunten, risico’s en het moment waarop opnieuw wordt geïnspecteerd of besloten.']],
      'gebouw-dossier-opbouwen' => [['Werk vanuit één herleidbare gebouwstructuur', 'Informatie wordt bruikbaarder wanneer foto’s, inspecties, tekeningen en werkzaamheden aan gebouw, bouwdeel en element kunnen worden gekoppeld.'], ['Bewaar besluiten naast technische informatie', 'Niet alleen wat is uitgevoerd, maar ook waarom een keuze is gemaakt helpt bij toekomstige beoordeling.'], ['Houd revisies actueel', 'Na uitvoering moeten gewijzigde gegevens, garanties en opleverinformatie terugkomen in het dossier zodat de volgende beslissing op de actuele situatie rust.']],
    ];
    return $guidance[$slug] ?? [];
  }

  private static function item(string $slug, string $title, string $summary): array {
    return [
      'slug' => $slug,
      'title' => $title,
      'summary' => $summary,
      'guidance' => self::guidance($slug),
      'public' => TRUE,
      'status' => KnowledgeApproval::STATUS_EDITORIAL,
      'ai_approved' => FALSE,
      'reviewed_by' => NULL,
      'reviewed_at' => NULL,
      'basis' => [
        'sources' => [],
        'validity_checked_at' => NULL,
        'notes' => 'Nog te voorzien van aantoonbare bron, geldigheidscontrole en deskundige beoordeling.',
      ],
    ];
  }

}
